tablefelsobalvekony3\"></td><td class=\"tablefelsovekony3\"></td><td class=\"tablefelsojobbvekony3\"></td></tr><tr><td class=\"tablebalvekony3\"></td><td class=\"tablebody\">\r\n";
       
            
            
            string pattern =
            @"kartya=(\d+).*?>" +          // ID
            @"(.*?)</a>\s*" +               // Card name
            @"\(([^()]+)\)<br>";            // Type

        var matches = Regex.Matches(
            input,
            pattern,
            RegexOptions.Singleline
        );

        var sb = new StringBuilder();

        foreach (Match match in matches)
        {
            string id = match.Groups[1].Value;
            string name = match.Groups[2].Value.Trim();
            string type = match.Groups[3].Value.Trim();

            sb.AppendLine($"{id} | {name} | {type}");
        }

        File.WriteAllText("Lovagi torna all.txt", sb.ToString(), Encoding.UTF8);
    }
